def transform(grid):
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    for r, row in enumerate(grid):
        # Complete a row that ends in background after a foreground run.
        cells = [c for c, v in enumerate(row) if v != bg]
        if cells:
            end = max(cells)
            if end < w - 1:
                for c in range(end + 1, w):
                    out[r][c] = 1
        # If this row repeats an earlier row's pattern with foreground cells
        # erased to background, mark those erased cells in the repeated pattern.
        for k in range(1, h):
            if r >= k:
                prev = grid[r-k]
                mismatch = [c for c in range(w) if prev[c] != bg and row[c] == bg]
                if mismatch and all(row[c] == prev[c] or row[c] == bg for c in range(w)):
                    for c in mismatch:
                        out[r][c] = 1
                    break
    return out

def transform(grid):
    # Extend the terminal contiguous run of foreground color to the right edge
    # only when that run has at least four cells.
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        c = len(row) - 1
        while c >= 0 and row[c] == bg:
            c -= 1
        if c < 0:
            continue
        color = row[c]
        start = c
        while start >= 0 and row[start] == color:
            start -= 1
        if c - start >= 4:
            for k in range(c + 1, len(row)):
                out[r][k] = 1
    return out
